
// Fonts
@import url('https://fonts.googleapis.com/css?family=Nunito');

// Variables
@import 'variables';

// Bootstrap
@import '~bootstrap/scss/bootstrap';

@import '~dropzone/dist/dropzone';

@import '~daterangepicker/daterangepicker.css';
@import '~pikaday/scss/pikaday';

@import 'message';

// Base styles
@import './base/base';

// Component styles
@import './components/components';

.status {
  text-transform: capitalize;
  
  &--pending {
    color: #FFA100;
  }

  &--assigned {
    color: #5FB500;
  }

  &--cancelled {
    color: #D0021B;
  }

  &--completed {
    color: #2371FE;
  }

  &--rejected {
    color: #D0021B;
  }
}

.text {
  color: #4A4A4A;

  &--gender {
    text-transform: capitalize;
  }
}

.label {
  margin-bottom: 0;
  line-height: 100%;
}

.job-types {
  list-style: none;
  padding: 0;
  margin-bottom: 20px;
  display: flex;
  justify-content: space-between;
  max-width: 310px;
}

.job-type {

  &-link {
    &--active {
      border-bottom: 1px solid #3490dc;
    }

    &:hover {
      text-decoration: none;
      color: #3490dc;
    }
  }
}

.alert-danger ul {
  margin-bottom: 0;
}

.terms {
  position: fixed;
  width: 100%;
  height: 100%;
  z-index: 1;
  background-color: #F2F2F2;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;

  &-title {
    h2 {
      margin-bottom: 28px;
    }

  }

  &-inner {
    background-color: #fff;
    max-width: 784px;
    padding: 20px 29px 12px 34px;
    margin-bottom: 22px;
  }
}

.admin-links {
    display: flex;
    max-width: 300px;
    margin: 20px auto 0;
    list-style: none;

    li {
      flex: 1;
      text-align: center;
    }
}

.radio-buttons {
    display: flex;
    max-width: 240px;
    justify-content: space-between;
    margin: auto;
}

.messages {
  text-align: center;
  position: absolute;
  z-index: 1;
  left: 50%;
  transform: translateX(-50%);
}